from taf.ul.chart.throughput.generator import AasyslogChartGenerator


class throughput(object):
    def __init__(self):
        self.acg = AasyslogChartGenerator()

    def generate(
        self,
        records,
        direction,
        ca,
        theoretical_throughput,
        average_tolerance,
        minimum_tolerance,
        output_dir=None,
        log_name_prefix=None,
        time_interval=1.024
    ):
        """
        Generate a html type file, containing operational throughput data chart.
        Default output file name: [{date}]_{cell_id}_{direction}.html

        Args:
            records: dict, origin throughput data with time-throughput matching, E.G from taf.analyzer.aasyslog
            direction: str, "UL" / "DL"
            ca: Bool, actCarrierAggregation, Define the chart should show data of each cell or combine togather.
            theoretical_throughput: str, target throughput value.(theory value) unit in Mbps!! E.G 2048.0
            average_tolerance: str, acceptable percent. E.G: 95%.
            minimum_tolerance: str, minimum percentage, E.G: 85%.
            output_dir: str(Optional), image file output directory, if None, will use current dir.
            log_name_prefix: str(Optional), the prefix of generated chart file.
            time_interval: float, the interval of each traffic data.

        Returns:
            str, The absolute path of generated chart file.


        Usage Example: Python
        from taf.ul.chart.throughput import throughput

        if __name__ == "__main__":
            records = {
                "5226497": [
                    {"record_time": "2023-06-20T21:13:47.247807Z", "throughput": 24936650},
                    {"record_time": "2023-06-20T21:13:48.247809Z", "throughput": 24936655},
                    {"record_time": "2023-06-20T21:13:49.247807Z", "throughput": 24936654},
                    {"record_time": "2023-06-20T21:13:50.247808Z", "throughput": 24936654},
                ]
            }  # records should be dict output of throughput analyzer library. E.G taf.analyzer.aasyslog_throughput
            tp_generator = throughput()
            chart_path = tp_generator.generate(
                direction="dl",
                ca=False,
                theoretical_throughput="1500.42",
                average_tolerance=0.95,
                minimum_tolerance=0.9,
                records=records,
                output_dir="/tmp/",
                log_name_prefix="test_aasyslog_generate_dl"
            ) # Chart will be generated and it's path will be return in generate.
        """
        return self.acg.generate(
            direction,
            ca,
            theoretical_throughput,
            average_tolerance,
            minimum_tolerance,
            records,
            output_dir,
            log_name_prefix,
            time_interval
        )
